# owner: platform
"""Contact sheet rows for substitute teachers."""

from rosterkit.errors import ProjectError


def _require_email(student):
    if not (student.email or "").strip():
        raise ProjectError(f"No email for student {student.display_name}")


def _join(row, widths):
    cells = [cell.ljust(size) for cell, size in zip(row, widths)]
    return "  ".join(cells).rstrip()


def _align(table):
    widths = [max(len(cell) for cell in column) for column in zip(*table)]
    return [_join(row, widths) for row in table]


# ---
def contact_rows(students):
    """Text rows of name, section and email, sorted by display name."""
    if not students:
        raise ProjectError("No students to put on the contact sheet")
    for student in students:
        _require_email(student)
    ordered = sorted(students, key=lambda item: item.display_name.casefold())
    return _align([(item.display_name, item.section, item.email) for item in ordered])
